// QF-MVP-50.7 fail-closed runtime preconditions for the stale sweep lane.
// Identical env contract to the certified 50.2E / 50.3 / 50.4 / 50.5 lanes. NO new
// variable is introduced by 50.6, and no secret VALUE is ever built or logged here.
const enabled = $env.QF_N8N_TRANSPORT_ENABLED === 'true';
const baseUrl = ($env.QF_CORE_STAGING_BASE_URL || '').replace(/\/$/, '');
const workerId = $env.QF_N8N_WORKER_ID || '';
const inbound = $env.QF_N8N_TO_CORE_HMAC_SECRET || '';
const response = $env.QF_CORE_TO_N8N_HMAC_SECRET || '';
const configured = Boolean(
  enabled &&
  /^https:\/\//.test(baseUrl) &&
  /^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(workerId) &&
  inbound.length >= 32 &&
  response.length >= 32 &&
  inbound !== response
);
return [{ json: {
  phase: 'QF-MVP-50.7',
  lane: 'cancel_stale',
  transportVersion: 1,
  configured,
  transportEnabled: enabled,
  secretSource: 'selfhost_env',
  workerId
} }];

// The EXACT three-key stale sweep body.
//
// n8n contributes NO job id, entity id, entity type, reason, safe code, status,
// force flag, batch size or limit. Core selects the job, proves the entity is
// gone and chooses the reason. Adding any field here would be rejected by the
// closed exact-key parse on the Core side, which is the point: this graph is
// structurally incapable of naming a job to cancel.
const requestId = $json.requestId;
const workerId = $env.QF_N8N_WORKER_ID || '';
if (!/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(requestId)) throw new Error('QF_50_7_CANCEL_STALE_REQUEST_ID_INVALID');
if (!/^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$/.test(workerId)) throw new Error('QF_50_7_CANCEL_STALE_WORKER_ID_INVALID');
const timestamp = Math.floor(Date.now() / 1000);
const rawBody = JSON.stringify({ transportVersion: 1, requestId, workerId });
return [{ json: { requestId, workerId, timestamp, rawBody } }];

const canonical = [
  'QF-AUTOMATION-TRANSPORT-V1',
  'N8N_TO_CORE',
  'POST',
  '/api/internal/automation/n8n/cancel-stale',
  $json.requestId,
  String($json.timestamp),
  $json.bodySha256
].join('\n');
return [{ json: { ...$json, requestCanonical: canonical } }];

// QF-MVP-50.7 signed transport. Same discipline as every certified 50.x POST node:
// request signing stays upstream, response verification stays downstream, and this
// node emits only plain, fully-serialisable data. No credential, secret value or
// business field is built here.
const items = $input.all();
if (items.length !== 1) throw new Error('QF_50_7_CANCEL_STALE_ITEM_COUNT_INVALID');
const input = items[0].json;
if (!input || typeof input !== 'object' || Array.isArray(input)) throw new Error('QF_50_7_CANCEL_STALE_INPUT_INVALID');

const pick = (o, k) => { try { return o === null || o === undefined ? undefined : o[k]; } catch (_) { return undefined; } };
const scalar = (v) => (typeof v === 'string' ? v : (typeof v === 'number' && Number.isFinite(v)) ? String(v) : null);

const requestId = scalar(input.requestId);
const timestamp = scalar(input.timestamp);
const bodySha256 = scalar(input.bodySha256);
const requestHmac = scalar(input.requestHmac);
if (!requestId || !timestamp || !bodySha256 || !requestHmac) throw new Error('QF_50_7_CANCEL_STALE_IDENTITY_INVALID');
if (/[\r\n\u0000]/.test(requestId + timestamp + bodySha256 + requestHmac)) throw new Error('QF_50_7_CANCEL_STALE_IDENTITY_UNSAFE');

const rawBody = input.rawBody;
if (typeof rawBody !== 'string' || rawBody.length === 0) throw new Error('QF_50_7_CANCEL_STALE_RAW_BODY_INVALID');
if (rawBody !== rawBody.trim()) throw new Error('QF_50_7_CANCEL_STALE_RAW_BODY_UNSTABLE');
try { JSON.parse(rawBody); } catch (_) { throw new Error('QF_50_7_CANCEL_STALE_RAW_BODY_NOT_JSON'); }

const baseUrl = String($env.QF_CORE_STAGING_BASE_URL || '').replace(/\/$/, '');
if (!/^https:\/\//.test(baseUrl)) throw new Error('QF_50_7_CANCEL_STALE_BASE_URL_INVALID');
const routePath = '/api/internal/automation/n8n/cancel-stale';
// The signed path and the requested path are the SAME value. The allowed set for
// this lane holds exactly ONE entry, so this graph can reach no other Core route
// — not claim, not execute, not complete, not recover, not reconcile.
const ALLOWED_PATHS = new Set([
  '/api/internal/automation/n8n/cancel-stale'
]);
if (!ALLOWED_PATHS.has(routePath)) throw new Error('QF_50_7_CANCEL_STALE_ROUTE_PATH_NOT_ALLOWED');
const url = baseUrl + routePath;

let httpResponse;
try {
  httpResponse = await this.helpers.httpRequest({
    method: 'POST',
    url: url,
    headers: {
      'content-type': 'application/json',
      'x-qf-transport-version': '1',
      'x-qf-request-id': requestId,
      'x-qf-timestamp': timestamp,
      'x-qf-body-sha256': bodySha256,
      'x-qf-signature': 'v1=' + requestHmac
    },
    body: rawBody,
    timeout: 10000,
    returnFullResponse: true,
    encoding: 'text',
    json: false,
    ignoreHttpStatusErrors: true,
    disableFollowRedirect: true
  });
} catch (error) {
  const raw = pick(error, 'code');
  const c = typeof raw === 'string' && /^[A-Za-z0-9_]{1,40}$/.test(raw) ? raw : 'UNKNOWN';
  throw new Error('QF_50_7_CANCEL_STALE_CALL_FAILED_' + c);
}

if (!httpResponse || typeof httpResponse !== 'object' || Array.isArray(httpResponse)) throw new Error('QF_50_7_CANCEL_STALE_RESULT_INVALID');
const statusCode = pick(httpResponse, 'statusCode');
const body = pick(httpResponse, 'body');
const headersIn = pick(httpResponse, 'headers');
if (!Number.isInteger(statusCode)) throw new Error('QF_50_7_CANCEL_STALE_STATUS_INVALID');
if (statusCode >= 300 && statusCode < 400) throw new Error('QF_50_7_CANCEL_STALE_REDIRECT_REFUSED');
if (typeof body !== 'string') throw new Error('QF_50_7_CANCEL_STALE_BODY_NOT_STRING');
if (!headersIn || typeof headersIn !== 'object' || Array.isArray(headersIn)) throw new Error('QF_50_7_CANCEL_STALE_HEADERS_INVALID');

let entries = Object.entries(headersIn);
if (entries.length === 0 && typeof pick(headersIn, 'entries') === 'function') {
  try { entries = Array.from(headersIn.entries()); } catch (_) { entries = []; }
}
const headers = {};
for (const pair of entries) {
  const name = String(pair[0]).toLowerCase();
  if (name === '__proto__') continue;
  if (Object.prototype.hasOwnProperty.call(headers, name)) continue;
  const value = pair[1];
  const normalized = Array.isArray(value) ? value.map(scalar).filter((x) => x !== null) : scalar(value);
  if (normalized === null) continue;
  headers[name] = normalized;
}
if (Object.keys(headers).length === 0) throw new Error('QF_50_7_CANCEL_STALE_HEADERS_EMPTY');

return [{ json: { statusCode: statusCode, body: body, headers: headers } }];

const response = $json;
const headers = response.headers || {};
const rawBody = typeof response.body === 'string' ? response.body : JSON.stringify(response.body ?? '');
const h = {};
for (const [k, v] of Object.entries(headers)) h[String(k).toLowerCase()] = Array.isArray(v) ? String(v[0] ?? '') : String(v ?? '');
return [{ json: {
  requestId: $('Build Exact Stale Sweep Body').first().json.requestId,
  statusCode: Number(response.statusCode),
  rawResponseBody: rawBody,
  responseVersion: h['x-qf-response-version'] || '',
  responseRequestId: h['x-qf-response-request-id'] || '',
  responseTimestamp: h['x-qf-response-timestamp'] || '',
  responseBodySha256Header: h['x-qf-response-body-sha256'] || '',
  responseSignature: h['x-qf-response-signature'] || '',
  exchange: 'cancel_stale'
} }];

const canonical = [
  'QF-AUTOMATION-TRANSPORT-V1',
  'CORE_TO_N8N_RESPONSE',
  '/api/internal/automation/n8n/cancel-stale',
  $json.responseRequestId,
  $json.responseTimestamp,
  $json.actualResponseBodySha256
].join('\n');
return [{ json: { ...$json, responseCanonical: canonical } }];

const now = Math.floor(Date.now() / 1000);
const ts = Number($json.responseTimestamp);
const expectedSig = 'v1=' + $json.expectedResponseHmac;
const checks = {
  version: $json.responseVersion === '1',
  requestId: $json.responseRequestId === $json.requestId,
  timestamp: /^\d{10}$/.test($json.responseTimestamp) && Number.isSafeInteger(ts) && Math.abs(now - ts) <= 300,
  bodyHash: /^[0-9a-f]{64}$/.test($json.responseBodySha256Header) && $json.responseBodySha256Header === $json.actualResponseBodySha256,
  signature: /^v1=[0-9a-f]{64}$/.test($json.responseSignature) && $json.responseSignature === expectedSig,
  status: Number.isInteger($json.statusCode) && $json.statusCode >= 200 && $json.statusCode < 600
};
const verified = Object.values(checks).every(Boolean);
return [{ json: { ...$json, verified, checks } }];

// THE STALE SWEEP IS TERMINAL FOR n8n IN EVERY OUTCOME.
//
// There is no branch that forwards work onward, because a cancelled job HAS no
// executable work by definition. This lane never executes, never completes, never
// recovers and never reconciles in response to anything Core says here.
//
// The three states below are the COMPLETE closed set; anything else stops the lane.
let payload;
try { payload = JSON.parse($json.rawResponseBody); } catch { throw new Error('QF_50_7_CANCEL_STALE_RESPONSE_JSON_INVALID'); }
if (!payload || typeof payload !== 'object' || payload.transportVersion !== 1 || payload.requestId !== $json.requestId) {
  throw new Error('QF_50_7_CANCEL_STALE_RESPONSE_ENVELOPE_INVALID');
}
if (payload.route !== 'cancel_stale_v1') throw new Error('QF_50_7_CANCEL_STALE_RESPONSE_ROUTE_INVALID');

const CLOSED_STATES = new Set(['cancel_stale_empty', 'cancel_stale_cancelled', 'rejected']);
if (!CLOSED_STATES.has(payload.orchestrationState)) throw new Error('QF_50_7_CANCEL_STALE_RESPONSE_STATE_INVALID');

// A rejection is an authenticated refusal, not a crash, and not something to retry
// from here: nothing was mutated and the next cycle will look again. An empty sweep
// is the ordinary steady state once the backlog is drained and is not an incident.
if (payload.orchestrationState === 'rejected' && payload.ok !== false) throw new Error('QF_50_7_CANCEL_STALE_REJECTION_INVARIANT');
if (payload.orchestrationState !== 'rejected' && payload.ok !== true) throw new Error('QF_50_7_CANCEL_STALE_SUCCESS_INVARIANT');

// Core's reason is a fixed repository constant. If a cancellation ever arrives
// carrying a different one, something other than this lane wrote it.
if (payload.orchestrationState === 'cancel_stale_cancelled' && payload.safeCode !== 'QF_AUTOMATION_BUSINESS_STATE_NO_LONGER_ELIGIBLE') {
  throw new Error('QF_50_7_CANCEL_STALE_SAFE_CODE_INVARIANT');
}

return [{ json: {
  lane: 'cancel_stale',
  orchestrationState: payload.orchestrationState,
  replayed: payload.replayed === true,
  // Observability only, and a CLOSED vocabulary word rather than an identifier.
  // This lane branches on orchestrationState and nothing else.
  actionType: typeof payload.actionType === 'string' ? payload.actionType : '',
  safeCode: typeof payload.safeCode === 'string' ? payload.safeCode : '',
  followUpCall: 'none'
} }];
